WITH h AS (
  SELECT s.id FROM superhero s WHERE s.race_id = 21 AND s.gender_id = 1
), p AS (
  SELECT h.id, COUNT(hp.power_id) AS n FROM h LEFT JOIN hero_power hp ON hp.hero_id = h.id GROUP BY h.id
)
SELECT COUNT(*) AS heroes, SUM(n) AS total_powers, ROUND(AVG(n)::numeric, 2) AS avg_powers FROM p

