WITH grp AS (
  SELECT p.id, p.sex FROM patient p
  WHERE p.birthday BETWEEN '1936-01-01' AND '1956-12-31'
  AND NOT EXISTS (SELECT 1 FROM laboratory l WHERE l.id = p.id AND l.cpk >= 250)
)
SELECT sex, COUNT(*), ROUND(100.0*COUNT(*)/SUM(COUNT(*)) OVER (), 1) AS pct FROM grp GROUP BY sex;
